command: python3 - <<'EOF'
import glob, re
try:
    import yaml
except ImportError:
    yaml = None

bad = []
for f in sorted(glob.glob("plugins/*/agents/*.md") + glob.glob("plugins/*/skills/*/SKILL.md")):
    text = open(f).read()
    m = re.match(r'^---\n(.*?)\n---\n', text, re.S)
    if not m:
        bad.append((f, "no frontmatter found"))
        continue
    if yaml:
        try:
            yaml.safe_load(m.group(1))
        except Exception as e:
            bad.append((f, str(e)))

if bad:
    for f, e in bad:
        print("BAD:", f, e)
else:
    print(f"All frontmatter blocks parse cleanly (yaml={'yes' if yaml else 'not installed, structural check only'})")
EOF
git status --short | wc -l
[/external_agent_tool_call]

